            Phrase("Please keep the marked emergency exit route clear.", "Anh/chị vui lòng giữ lối thoát hiểm được đánh dấu thông thoáng.", "Nói rõ từ khóa, ngắt câu tự nhiên và giữ giọng lịch sự với khách.", id = "hotel_hk_emergency_p8"),
        ), listOf(
            ConversationTurn("I slipped in the bathroom.", "Tôi bị trượt ngã trong phòng tắm.", "I am sorry. I will alert our emergency response team immediately.", "Tôi rất tiếc. Tôi sẽ báo đội ứng phó khẩn cấp ngay.", id = "hotel_hk_emergency_t1"),
            ConversationTurn("My partner needs medical help.", "Người đi cùng tôi cần hỗ trợ y tế.", "Please tell me the room number and exact location.", "Anh/chị vui lòng cho biết số phòng và vị trí chính xác.", id = "hotel_hk_emergency_t2"),
            ConversationTurn("Can you give me some medicine?", "Anh/chị cho tôi thuốc được không?", "I cannot recommend medication, but I can contact the appropriate assistance.", "Tôi không thể khuyến nghị thuốc, nhưng có thể liên hệ người hỗ trợ phù hợp.", id = "hotel_hk_emergency_t3"),
            ConversationTurn("There is smoke outside my room.", "Có khói bên ngoài phòng tôi.", "I will notify security now. Please follow the emergency team's instructions.", "Tôi sẽ báo an ninh ngay. Vui lòng làm theo hướng dẫn của đội ứng phó.", id = "hotel_hk_emergency_t4"),
            ConversationTurn("I need help with the evacuation.", "Tôi cần hỗ trợ khi sơ tán.", "I will tell the team where you are and what assistance you need.", "Tôi sẽ báo đội ứng phó vị trí và nhu cầu hỗ trợ của anh/chị.", id = "hotel_hk_emergency_t5"),
            ConversationTurn("Is it safe to go back inside?", "Đã an toàn để quay lại bên trong chưa?", "Please wait for clearance from the emergency team before re-entering.", "Vui lòng chờ đội ứng phó cho phép trước khi quay lại bên trong.", id = "hotel_hk_emergency_t6"),
        ))),
    ).let(HotelExpansion::expand)
    val all: List<Lesson> = topics.map { it.lesson }
    fun isHotel(lesson: Lesson) = lesson.id.startsWith("hotel_fo_") || lesson.id.startsWith("hotel_hk_")
    fun role(lesson: Lesson) = if (lesson.id.startsWith("hotel_fo_")) "FO" else "HK"
    fun roleLabel(role: String) = if (role == "FO") "Lễ tân" else "Buồng phòng"
    fun roleEnglish(role: String) = if (role == "FO") "Front Office" else "Housekeeping"
    fun lessons(role: String) = topics.filter { it.role == role }.map { it.lesson }
    val exercises: List<SpeakingExercise> = topics.map { topic ->
        SpeakingExercise("exercise_${topic.lesson.id}", "Khách sạn", topic.lesson.id, topic.lesson.vietnamese,
            topic.lesson.phrases.map { phrase -> ExerciseQuestion("exercise_${phrase.id}", phrase.vietnamese, listOf(phrase.english)) })
    }
}
